LEGACY = [('../index.html', 'nav_home'), ('../rules.html', 'nav_rules'), ('../releases.html', 'nav_releases'), ('../transparency.html', 'nav_transparency'), ('../docs/index.html', 'nav_docs')]

def e(s): return html.escape(s, quote=True)
def T(tag, key, cls='', extra=''):
    return f'<{tag}{(" class=" + chr(34) + cls + chr(34)) if cls else ""}{extra} data-t="{key}">{e(S[key][0])}</{tag}>'

def chrome(file, page, body, scripts_note=''):
    nav = ''.join(f'<a href="{h}" data-t="{k}"{" aria-current=" + chr(34) + "page" + chr(34) if p == file[:-5] else ""}>{e(S[k][0])}</a>' for h, k, p in NAV)
    leg = ''.join(f'<a href="{h}" data-t="{k}">{e(S[k][0])}</a>' for h, k in LEGACY)
    ttl = S['title_' + page][0]
    return ('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            f'<title>{e(ttl)} · {SITE}</title><link rel="stylesheet" href="../style.css"><link rel="stylesheet" href="intel.css">\n'
            f'<body data-page="{page}"><a class="skip" href="#main" data-t="skip">{e(S["skip"][0])}</a>'
            f'<aside><h2>🛡 MacGuard</h2><small>Security Intelligence</small><nav aria-label="Security Intelligence">{nav}</nav>'
            f'<nav class="legacy" aria-label="YARA">{leg}</nav></aside>'
            '<main id="main"><header><div><small>MACGUARD SECURITY</small>'
            f'{T("h1", "h_" + page)}{T("p", "p_" + page)}</div>'
            '<div><select id="lang" aria-label="Idioma / Language"><option value="es">Español</option><option value="en">English</option></select>'
            '<button id="theme" type="button" aria-label="Claro / oscuro · Light / dark">◐</button></div></header>\n'
            f'<p id="load-state" role="status" data-t="loading">{e(S["loading"][0])}</p>\n{body}\n'
            f'{T("p", "note_data_lang", "muted")}\n{T("footer", "disclaimer")}</main>'
            '<script src="../common.js"></script><script src="intel-i18n.js"></script><script src="intel.js"></script></html>\n')

def noscript(*files):
    links = ' · '.join(f'<a href="../api/v1/{f}">api/v1/{f}</a>' for f in files)
    return f'<noscript><p class="notice">{e(S["noscript"][0])} {links}</p></noscript>'

def section(hid, key, inner):
    return f'<section class="panel" aria-labelledby="{hid}">{T("h2", key, extra=" id=" + chr(34) + hid + chr(34))}{inner}</section>\n'

def label(i, key, control):
    return f'<label>{T("span", key)} {control}</label>'

def body(page):
    if page == 'overview':
        go = ''.join(f'<article class="panel"><h3><a href="{h}" data-t="go_{k}">{e(S["go_" + k][0])}</a></h3>{T("p", "d_" + k)}</article>'
                     for h, k in (('explorer.html', 'explorer'), ('channels.html', 'channels'), ('artifacts.html', 'artifacts'), ('downloads.html', 'downloads'), ('provenance.html', 'provenance'),
                                  ('licenses.html', 'licenses'), ('security.html', 'security'), ('roadmap.html', 'roadmap')))
        yara = ''.join(f'<li><a href="{h}" data-t="{k}">{e(S[k][0])}</a></li>' for h, k in LEGACY[1:])
        return (section('ov-h', 'h_ov_state', '<div id="ov"></div>') + section('lg-h', 'h_ov_legend', '<div id="legend"></div>') +
                f'<section aria-labelledby="go-h"><h2 id="go-h" data-t="h_ov_go">{e(S["h_ov_go"][0])}</h2><div class="grid3 gofour">{go}</div></section>\n' +
                section('yara-h', 'h_ov_yara', f'{T("p", "p_ov_yara")}<ul class="dl">{yara}</ul>') + noscript('channels.json', 'index.json'))
    if page == 'explorer':
        sels = ''.join(label(k, 'f_' + k, f'<select id="f-{k}"><option value="">{e(S["all"][0])}</option></select>') for k in ('src', 'fam', 'lic', 'os', 'st'))
        flt = (f'<div class="toolbar" role="search" aria-labelledby="flt-h">'
               f'<label>{T("span", "f_q")} <input id="f-q" type="search" autocomplete="off"></label>{sels}'
               f'<button id="f-reset" type="button" data-t="f_reset">{e(S["f_reset"][0])}</button></div>'
               f'<p id="count" role="status" aria-live="polite"></p>{T("p", "p_explorer_missing", "muted")}')
        return (section('flt-h', 'flt_h', flt) + f'<section aria-labelledby="res-h">{T("h2", "res_h", "sr", " id=" + chr(34) + "res-h" + chr(34))}<ul class="cardlist" id="results"></ul></section>\n' + noscript('channels.json'))
    if page == 'channels':
        return section('lg-h', 'h_ov_legend', '<div id="legend"></div>') + '<section class="panel"><div id="ch"></div></section>\n' + noscript('channels.json')
    if page == 'artifacts':
        return '<div id="cards"></div>\n' + noscript('index.json', 'cards/ioc-1.json', 'cards/vulns-1.json', 'cards/yara-legacy.json')
    if page == 'downloads':
        return (section('dly-h', 'h_dl_yara', '<div id="dl-yara"></div>') + section('dln-h', 'h_dl_new', f'{T("p", "p_dl_new")}<div id="dl-new"></div>') +
                section('dlm-h', 'h_dl_meta', f'{T("p", "p_dl_meta")}<div id="dl-meta"></div>') + noscript('index.json'))
    if page == 'provenance':
        flt = (f'<div class="toolbar">{label("g", "f_pv_grp", "<select id=" + chr(34) + "pv-grp" + chr(34) + "><option value=" + chr(34) + chr(34) + ">" + e(S["all"][0]) + "</option></select>")}'
               f'{label("c", "f_pv_cov", "<select id=" + chr(34) + "pv-cov" + chr(34) + "><option value=" + chr(34) + chr(34) + ">" + e(S["all"][0]) + "</option></select>")}</div>'
               '<p id="pv-count" role="status" aria-live="polite"></p>')
        return (section('pvs-h', 'h_pv_status', '<div id="pv-status"></div>') + section('pvw-h', 'h_pv_why', T('p', 'p_pv_why')) + section('pvf-h', 'h_pv_facts', '<div id="pv-facts"></div>') +
                section('pvr-h', 'h_pv_rules', '<div id="pv-rules"></div>') +
                section('pvc-h', 'h_pv_cov', f'{T("p", "p_pv_cov")}<div class="tiles" id="pv-counts"></div><div id="pv-meaning"></div>{flt}<div id="pv-cov-table"></div>') +
                section('pvl-h', 'h_pv_limits', '<div id="pv-limits"></div>') + noscript('provenance.json'))
    if page == 'licenses':
        flt = (f'<div class="toolbar">{label("v", "f_lic_v", "<select id=" + chr(34) + "lic-v" + chr(34) + "><option value=" + chr(34) + chr(34) + ">" + e(S["all"][0]) + "</option></select>")}'
               f'<label>{T("span", "f_lic_q")} <input id="lic-q" type="search" autocomplete="off"></label></div><p id="lic-count" role="status" aria-live="polite"></p>')
        return ('<section class="panel"><div id="lic-top"></div></section>\n' + section('lc-h', 'h_lic_counts', '<div class="tiles" id="lic-counts"></div>') +
                section('lr-h', 'h_lic_registry', '<div id="lic-registry"></div>') + section('lm-h', 'h_lic_matrix', f'{flt}<div id="lic-matrix"></div>') + noscript('licenses.json', 'sources.json'))
    if page == 'security':
        chain = '<ul class="dl">' + ''.join(T('li', k) for k in ('sec_c1', 'sec_c2', 'sec_c3')) + '</ul>'
        notg = '<ul class="dl">' + ''.join(T('li', k) for k in ('sec_n1', 'sec_n2', 'sec_n3', 'sec_n4')) + '</ul>'
        docs = '<ul class="dl">' + ''.join(f'<li><a href="../docs/es/{s}.html" data-doc="{s}" data-t="{k}">{e(S[k][0])}</a></li>' for s, k in
                                          (('threat-model', 'doc_threat'), ('limits', 'doc_limits'), ('verification', 'doc_verification'), ('sigstore', 'doc_sigstore'))) + '</ul>'
        return (section('sc-h', 'h_sec_chain', chain) + section('sn-h', 'h_sec_not', notg) + section('ss-h', 'h_sec_sig', '<div id="sec-sig"></div>') +
                section('sp-h', 'h_sec_privacy', T('p', 'sec_privacy')) + section('sr-h', 'h_sec_report', T('p', 'sec_report')) + section('sd-h', 'h_sec_docs', docs) + noscript('index.json'))
    if page == 'roadmap':
        return '<div id="rm"></div>\n' + noscript('roadmap.json')
    raise KeyError(page)

def i18n_js():
    es = {k: v[0] for k, v in sorted(S.items())}
    en = {k: v[1] for k, v in sorted(S.items())}
    return ('/* Generated by scripts/gen_intel_pages.py from one table of strings: do not edit by hand. Spanish is the default of the HTML; both languages have every key. */\n'
            'window.INTEL_I18N = ' + json.dumps({'es': es, 'en': en}, ensure_ascii=False, indent=1, sort_keys=True) + ';\n')

def outputs():
    out = {'intel-i18n.js': i18n_js()}
    for f, (page, _, _) in PAGES.items():
        out[f + '.html'] = chrome(f + '.html', page, body(page))
    return out

def main(argv):
    out = outputs()
    if '--check' in argv:
        bad = [n for n, s in out.items() if not (OUT / n).exists() or (OUT / n).read_text(encoding='utf-8') != s]
        print('gen_intel_pages:', 'differs: ' + ', '.join(bad) if bad else 'matches')
        return 1 if bad else 0
    OUT.mkdir(parents=True, exist_ok=True)
    for n, s in out.items(): (OUT / n).write_text(s, encoding='utf-8')
    print(f'wrote {len(out)} files under web/intelligence')
    return 0

if __name__ == '__main__': sys.exit(main(sys.argv[1:]))
